
import os
f = 'src/modules/catalog/models.py'
with open(f, 'r', encoding='utf-8') as file:
    content = file.read()

# حذف هر چیزی از اولین خطی که 'class Product' دارد به بعد
lines = content.split('\n')
clean_lines = []
for line in lines:
    if line.startswith('class Product(models.Model):'):
        break
    clean_lines.append(line)

clean_content = '\n'.join(clean_lines).rstrip()

# نوشتن محتوای پاک شده (فقط Category و Supplier)
with open(f, 'w', encoding='utf-8') as file:
    file.write(clean_content + '\n')

# حالا کد کامل Product را اضافه کن
import base64
full_product_b64 = ''
full_product = base64.b64decode(full_product_b64).decode('utf-8')

with open(f, 'a', encoding='utf-8') as file:
    file.write(full_product)

print('FIX SUCCESS: models.py repaired with full Product model')
